  string ForecastPc(System.Collections.Generic.IEnumerable<string> laws,System.Collections.Generic.IEnumerable<string> upgrades,int[] links){
   try{var rates=Sim.PreviewRates(laws,upgrades,links);Sim.RefreshRates();return "RATE ESTIMATE / same installed production and stock\n"+string.Join("\n",Enumerable.Range(0,12).Where(i=>Sim.StageOpen(i/2)).Select(i=>GameSession.Content.resources[i]+": "+new Number(Sim.CachedRate(i))+" → "+rates[i]+" /s"))+"\nInputs can run out later; this is not a time forecast.";}catch{return "This stored profile requires correction before a rate preview is available.";}
  }
  void StrategyTransferPc(){
   var dialog=ModalPc("Strategy import / export",880,690);Label("Stable IDs include Ascension choices, laws and Resonance Links. Import stores a preset without awarding or spending points.",dialog,18,75);
   var field=PcBox("Strategy JSON",dialog,CosmicStyle.Background,240);field.gameObject.AddComponent<UnityEngine.UI.RectMask2D>();var input=field.gameObject.AddComponent<TMPro.TMP_InputField>();var text=(TMPro.TextMeshProUGUI)PcText("",field,16);Stretch((RectTransform)text.transform,Vector2.zero,Vector2.one,new Vector2(12,12),new Vector2(-12,-12));input.textComponent=text;input.textViewport=field;input.lineType=TMPro.TMP_InputField.LineType.MultiLineNewline;input.characterLimit=16384;
   for(int i=0;i<3;i++){int slot=i;var row=HRow(dialog,"Transfer profile "+i,44);PcButton("Show "+Sim.Meta.strategies[i].name,row,()=>input.text=JsonUtility.ToJson(Sim.Meta.strategies[slot],true));PcButton("Import to slot "+(i+1),row,()=>{try{if(!Sim.ImportStrategy(slot,JsonUtility.FromJson<StrategyProfile>(input.text)))throw new Exception("Invalid preset");ClosePcModal();ShowPc();}catch{ToastPc("Preset rejected. Check IDs, links and JSON.");}});}
   PcButton("Close",dialog,ClosePcModal);
  }
  bool ExpansionTabVisible(string p)=>p=="Megastructures"||p=="Reality laws"?Sim!=null&&Sim.HasLayer(1):p=="Parallel universes"?Sim!=null&&Sim.UniverseCapacity>1:true;
