   for(int i=0;i<ExpansionContent.Laws.Length;i++){var law=ExpansionContent.Laws[i];var c=GridCard(law.name,230);Caption(new[]{"FLUX","TIME","GEOMETRY"}[law.family],c);Label(law.name,c,28,40);Label(law.description,c,18,65,CosmicStyle.Muted);bool active=Sim.Meta.laws.Contains(law.id);var b=PcButton(active?"Active / remove":"Preview and select",c,()=>{var next=Sim.Meta.laws.Where(id=>Array.Find(ExpansionContent.Laws,x=>x.id==id).family!=law.family).ToList();if(!active)next.Add(law.id);ConfirmPc(law.name,ForecastPc(next,Sim.Meta.ascensionUpgrades,null)+"\n\n"+law.description+"\n\nResulting loadout: "+string.Join(", ",next)+"\nThe change creates no resources, refunds or reset awards. Numerical output depends on input bottlenecks.",()=>{if(!Sim.SetLaws(next))ToastPc("Law capacity or 10-minute switch cooldown prevents this change.");ShowPc();},"Apply laws");});var reason=Label("",c,18,0,CosmicStyle.Muted);Bind(()=>{double remaining=Math.Max(0,Sim.Meta.lawReadyAt-S.time);bool capacity=active||Sim.Meta.laws.Any(id=>Array.Find(ExpansionContent.Laws,l=>l.id==id).family==law.family)||Sim.Meta.laws.Count<Sim.LawSlots;reason.text=remaining>0?"Switch available in "+OfflineReport.Duration(remaining):!capacity?"All law slots occupied. Remove a law first.":active?"Active in the home universe":"Ready to preview";b.interactable=remaining<=0&&capacity;});}FinishGrid();
