  void UniverseDetailsPc(int id){
   var sim=Sim.Universe(id);var dialog=ModalPc("Parallel universe "+id,930,750);PcButton("Close",dialog,ClosePcModal);var content=dialog;
   for(int i=0;i<24;i++){if(!sim.Open(GameSession.Content.generators[i]))continue;int generator=i;var c=PCard(content,GameSession.Content.generators[i].name);Label(GameSession.Content.generators[i].name+" ×"+sim.S.owned[i],c,23,38);Label("Output "+new Number(sim.Flow(i))+" /s  /  Cost "+new Number(sim.Cost(i)),c,17,34);PcButton("Buy Max",c,()=>{Sim.EditUniverse(id,u=>u.Buy(generator,u.MaxBuy(generator)));UniverseDetailsPc(id);});}
   foreach(var law in ExpansionContent.Laws){var l=law;PcButton((sim.Meta.laws.Contains(l.id)?"ACTIVE / ":"Law / ")+l.name+" / "+l.description,content,()=>{Sim.EditUniverse(id,u=>{var next=u.Meta.laws.Where(x=>Array.Find(ExpansionContent.Laws,d=>d.id==x).family!=l.family).ToList();if(!u.Meta.laws.Contains(l.id))next.Add(l.id);u.SetLaws(next);});UniverseDetailsPc(id);},62);}
   foreach(int resource in new[]{0,1}){int r=resource;var row=HRow(content,"Route "+r,48);PcButton(GameSession.Content.resources[r]+" → Home",row,()=>{Sim.ScheduleTransfer(id,0,r);UniverseDetailsPc(id);});PcButton("Home → "+GameSession.Content.resources[r],row,()=>{Sim.ScheduleTransfer(0,id,r);UniverseDetailsPc(id);});}foreach(var other in Sim.Meta.universes){if(other.id==id)continue;int target=other.id;PcButton("Route Energy → Universe "+target,content,()=>{Sim.ScheduleTransfer(id,target,0);UniverseDetailsPc(id);});}PcButton("Close",dialog,ClosePcModal);
